const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,selected=[],ministryId='vivienda',view='matrix',community='',metricId='',markId='',cardFocus='',scrollToCard=false,lastFocus;
const party=id=>data.parties.find(p=>p.id===id);
const label=id=>id==='FA'?'Frente Amplio':id;
const ministry=()=>data.ministries.find(item=>item.id===ministryId);
const proposal=(id,current=ministryId)=>data.proposals.find(item=>item.party===id&&item.ministry===current);
const ids=()=>[...selected].sort((a,b)=>a.localeCompare(b,'es'));
const leadRank=item=>{const id=item.id;if(id==='PP'||id==='UPN-PP')return 0;if(id==='PSOE'||id==='PSC'||id==='PSdeG-PSOE'||id==='PSIB-PSOE'||id==='PSN-PSOE')return 1;if(id==='FA'||/frente amplio|front ampli/i.test(id+' '+item.name))return 2;if(id==='VOX')return 3;return 4;};
const speakers=()=>data.parties.filter(item=>inCommunity(item)&&proposal(item.id)?.status==='contrastada').sort((a,b)=>leadRank(a)-leadRank(b)||a.id.localeCompare(b.id,'es')).map(item=>item.id);
const visible=()=>selected.length?speakers().filter(id=>selected.includes(id)):speakers();
const programOf=item=>item&&item.program&&typeof item.program==='object'?item.program:null;
const tags={'financiacion':'Financiación','oferta-publica':'Oferta pública','incentivos':'Incentivos fiscales y ayudas','regulacion':'Regulación','coordinacion':'Coordinación y gestión','reforma':'Reformas normativas','energia':'Política energética','servicios-publicos':'Servicios públicos','autogobierno':'Autogobierno','adaptacion':'Adaptación'};
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600);}
function inCommunity(item){if(!community)return true;const current=data.communities.find(entry=>entry.id===community);return !!current&&item.provinces.some(code=>current.provinces.includes(code));}
function syncUrl(){const q=new URLSearchParams({parties:ids().join('|'),ministry:ministryId,view,community});if(markId)q.set('mark',markId);if(cardFocus)q.set('card',cardFocus);history.replaceState(null,'','#'+q);}
function readUrl(){try{const q=new URLSearchParams(location.hash.slice(1));if(q.has('parties'))selected=q.get('parties').split('|').filter(id=>party(id));const requested=q.get('ministry')||q.get('topic');if(data.ministries.some(item=>item.id===requested))ministryId=requested;if(['matrix','routes','warnings'].includes(q.get('view')))view=q.get('view');if(data.communities.some(item=>item.id===q.get('community')))community=q.get('community');selected=selected.filter(id=>inCommunity(party(id)));if(selected.length===4&&['FA','PP','PSOE','VOX'].every(id=>selected.includes(id)))selected=[];markId=q.get('mark')||'';if(markId&&!data.proposals.some(item=>item.id===markId))markId='';cardFocus=q.get('card')||'';if(cardFocus&&!data.proposals.some(item=>item.id===cardFocus))cardFocus='';scrollToCard=!!cardFocus;}catch{}}
function toggleParty(id){selected=selected.includes(id)?selected.filter(item=>item!==id):selected.concat(id);render();}
function partyStatus(item){if(!programOf(item))return 'No tiene programa';if(!item.reviewed)return 'Documento localizado, contraste pendiente';return 'Programa contrastado';}
function renderParties(){const q=$('partySearch').value.toLocaleLowerCase('es');const rows=data.parties.filter(item=>inCommunity(item)&&(!q||(item.id+' '+item.name).toLocaleLowerCase('es').includes(q))).sort((a,b)=>label(a.id).localeCompare(label(b.id),'es'));$('partyList').innerHTML=rows.map(item=>`<label class="partyoption" title="${esc(partyStatus(item))}"><input type="checkbox" value="${esc(item.id)}" ${selected.includes(item.id)?'checked':''}><i class="swatch" style="background:${item.color}"></i><span class="partyname">${esc(label(item.id))}</span></label>`).join('')||'<p class="muted">No hay candidaturas de esta comunidad con esta búsqueda.</p>';$('partyList').querySelectorAll('input').forEach(input=>input.onchange=()=>toggleParty(input.value));const place=community?data.communities.find(item=>item.id===community).name:'el catálogo';$('partyCount').textContent=`${rows.length} en ${place}. Marca alguna si quieres ver solo esas.`;}
function renderMinistries(){$('topics').innerHTML=data.ministries.map(item=>`<button data-ministry="${item.id}" class="${ministryId===item.id?'active':''}" aria-pressed="${ministryId===item.id}">${esc(item.short)}</button>`).join('');$('topics').querySelectorAll('button').forEach(button=>button.onclick=()=>{ministryId=button.dataset.ministry;render();});}
function heading(label,note){return `<div class="comparisonTitle"><h3>${esc(label)}</h3><span>${esc(note)}</span></div>`;}
function sourceLabel(item){return item.page?`PDF · página ${item.page}`:(item.locator||'Documento oficial');}
function renderCard(id){const item=party(id),card=proposal(id);if(!card){if(!programOf(item))return `<article class="proposalcard absent" style="--party:${item.color}"><div class="cardparty"><i class="swatch" style="background:${item.color}"></i>${esc(label(id))}<small>SIN PROGRAMA</small></div><h4>No tiene programa</h4><p>No hay una referencia explícita al programa. No se elabora ficha.</p></article>`;return `<article class="proposalcard pending" style="--party:${item.color}"><div class="cardparty"><i class="swatch" style="background:${item.color}"></i>${esc(label(id))}<small>PENDIENTE</small></div><h4>Contraste pendiente</h4><p>Hay un documento localizado y todavía no hay fichas contrastadas.</p></article>`;}if(card.status==='sin-medida'){return `<article class="proposalcard absent" style="--party:${item.color}"><div class="cardparty"><i class="swatch" style="background:${item.color}"></i>${esc(label(id))}<small>SIN PUNTO CONTRASTADO</small></div><h4>Sin punto en este ministerio</h4><p>${esc(card.summary)}</p><button class="sourcebutton" data-proposal="${esc(card.id)}"><span>Documento consultado</span><span>Ver fuente ↗</span></button></article>`;}const quote=card.excerpt&&card.excerpt!==card.summary?`<blockquote class="excerpt">${esc(card.excerpt)}</blockquote>`:'';const warned=!!card.warning||(card.reading&&card.reading.label==='fascista')||(card.also&&card.also.reading&&card.also.reading.label==='fascista');const mark=warned?`<button type="button" class="marklink" data-mark="${esc(card.id)}">${card.warning?'Advertencia: este pasaje tensiona la pluralidad, la inclusión o el Estado del bienestar.':'Este pasaje cumple un indicador de la definición de trabajo.'} <span>Por qué ↗</span></button>`:'';const more=card.also?`<a class="sourcebutton" href="${esc(card.also.url+(card.also.page?'#page='+card.also.page:''))}" target="_blank" rel="noopener noreferrer"><span>${esc(card.also.page?`PDF · página ${card.also.page}`:(card.also.locator||'Otro programa'))}</span><span>Otro programa ↗</span></a>`:'';return `<article class="proposalcard${warned?' warned':''}" data-card="${esc(card.id)}" style="--party:${item.color}"><div class="cardparty"><i class="swatch" style="background:${item.color}"></i>${esc(label(id))}<small>FUENTE CONTRASTADA</small></div><h4>${esc(card.title)}</h4><p>${esc(card.summary)}</p>${quote}${mark}<button class="sourcebutton" data-proposal="${esc(card.id)}"><span>${esc(sourceLabel(card))}</span><span>Ver fuente ↗</span></button>${more}</article>`;}
function renderMatrix(){const current=ministry();const rows=visible();const note=rows.length===1?'1 candidatura con un punto contrastado':`${rows.length} candidaturas con un punto contrastado`;if(!rows.length)return heading(current.name,'Nadie recoge un punto contrastado')+'<div class="nodata">Ninguna candidatura de este ámbito tiene una cita contrastada para este ministerio.</div>';return heading(current.name,note)+`<div class="cards">${rows.map(renderCard).join('')}</div>`;}
function renderRoutes(){const rows=visible().map(id=>proposal(id)).filter(item=>item&&item.status==='contrastada');const tagged=rows.filter(item=>item.tags&&item.tags.length);const plain=rows.filter(item=>!(item.tags&&item.tags.length));const groups=[...new Set(tagged.flatMap(item=>item.tags))].filter(tag=>tags[tag]).sort((a,b)=>tags[a].localeCompare(tags[b],'es'));const chip=item=>`<button data-proposal="${esc(item.id)}"><i class="swatch" style="background:${party(item.party).color}"></i>${esc(label(item.party))} <span>↗</span></button>`;const blocks=groups.map(tag=>`<article class="route"><h4>${esc(tags[tag])}</h4><div class="routepath">${tagged.filter(item=>item.tags.includes(tag)).map(chip).join('')}</div></article>`);if(plain.length)blocks.push(`<article class="route"><h4>Sin instrumento citado</h4><div class="routepath">${plain.map(chip).join('')}</div></article>`);const note=rows.length===1?'1 candidatura con un punto contrastado':`${rows.length} candidaturas con un punto contrastado`;return heading('¿Por qué vías actúan?',note)+'<p class="viznote">Una ficha puede citar varios instrumentos. Estos grupos no son posiciones ideológicas ni miden el peso del ministerio en el programa. Debajo están las mismas fichas que en cara a cara.</p>'+`<div class="routes">${blocks.join('')||'<div class="nodata">Ninguna candidatura de este ámbito tiene una cita contrastada.</div>'}</div>`+`<div class="cards">${visible().map(renderCard).join('')}</div>`;}
function renderWarnedCard(card){const item=party(card.party);const current=data.ministries.find(entry=>entry.id===card.ministry);const quote=card.excerpt&&card.excerpt!==card.summary?`<blockquote class="excerpt">${esc(card.excerpt)}</blockquote>`:'';const mark=`<button type="button" class="marklink" data-mark="${esc(card.id)}">Advertencia: este pasaje tensiona la pluralidad, la inclusión o el Estado del bienestar. <span>Por qué ↗</span></button>`;return `<article class="proposalcard warned" data-card="${esc(card.id)}" style="--party:${item.color}"><div class="cardparty"><i class="swatch" style="background:${item.color}"></i>${esc(label(card.party))}<small>${esc(current?current.short:card.ministry)}</small></div><h4>${esc(card.title)}</h4><p>${esc(card.summary)}</p>${quote}${mark}<button class="sourcebutton" data-proposal="${esc(card.id)}"><span>${esc(sourceLabel(card))}</span><span>Ver fuente ↗</span></button></article>`;}
function renderWarnings(){const byId=Object.fromEntries(data.proposals.filter(card=>card.warning).map(card=>[card.id,card]));const groups=[['Remigración y derechos de quien migra',['FE de las JONS-inclusion','VOX-inclusion','SALF-inclusion','IE-inclusion','VOX-vivienda','FE de las JONS-interior']],['Mujeres y personas LGTBIQ+',['FE de las JONS-igualdad','FO-igualdad','PUEDE-igualdad']],['Escuela y cultura',['IE-educacion','FO-cultura']]];const intro=`<div class="warnintro"><h3>Por qué no hay que normalizarlas.</h3><p>Normalizarlas es aceptar como parte del debate ordinario que un grupo vulnerable pague por problemas que son de todos. La vivienda, el empleo, la escuela o la inseguridad tienen causas de oferta, de salarios, de servicios y de leyes. Estos pasajes se las atribuyen a quien migra, a las mujeres, a las personas LGTBIQ+ o a quien no encaja en una sola idea de nación, y presentan el recorte de sus derechos como una defensa.</p><p>El peligro está en la costumbre. Cuando la pérdida de derechos de un grupo se vuelve un argumento más, resulta más fácil vigilar, censurar o retirar protección a quien la cuestione. El miedo divide a quien comparte barrio, escuela y trabajo, y debilita la solidaridad que sostiene los derechos de todas las personas.</p><p>Aquí están juntas las fichas que ya llevan advertencia, para leerlas de un vistazo. La marca es del pasaje, no de la candidatura, y no recomienda un voto.</p></div>`;const blocks=groups.map(([title,ids])=>{const cards=ids.map(id=>byId[id]).filter(Boolean);if(!cards.length)return '';return `<section class="warnset"><h3>${esc(title)}</h3><div class="cards">${cards.map(renderWarnedCard).join('')}</div></section>`;}).join('');return intro+blocks;}
function render(){renderParties();renderMinistries();const shown=visible();const warned=data.proposals.filter(card=>card.warning);$('selectionCount').textContent=view==='warnings'?warned.length+' con advertencia':shown.length+' con cita';$('topics').hidden=view==='warnings';$('partyFilter').hidden=view==='warnings';$('canvasEyebrow').textContent=view==='warnings'?'02 / RECOPILACIÓN':'01 / EXPLORA POR MINISTERIO';$('canvasTitle').textContent=view==='warnings'?'Propuestas que no hay que normalizar':'Las propuestas, en perspectiva';$('viewStatus').textContent=$('canvasTitle').textContent;document.querySelectorAll('[data-view]').forEach(button=>{button.classList.toggle('active',button.dataset.view===view);button.setAttribute('aria-pressed',button.dataset.view===view);});$('selectedTags').hidden=!selected.length;$('selectedTags').innerHTML=selected.length?ids().map(id=>`<button data-remove="${esc(id)}" aria-label="Quitar ${esc(label(id))}"><i class="swatch" style="background:${party(id).color}"></i>${esc(label(id))} <span>×</span></button>`).join(''):'';$('selectedTags').querySelectorAll('button').forEach(button=>button.onclick=()=>toggleParty(button.dataset.remove));$('visualization').innerHTML=view==='warnings'?renderWarnings():view==='routes'?renderRoutes():renderMatrix();bindProposals();$('visualization').querySelectorAll('[data-mark]').forEach(button=>button.onclick=()=>openMark(button.dataset.mark));$('visualization').querySelectorAll('[data-library]').forEach(button=>button.onclick=()=>{showPage('library');$('sourceSearch').value=button.dataset.library;renderLibrary();});if($('metric'))$('metric').onchange=()=>{metricId=$('metric').value;const chosen=(data.metrics||[]).find(item=>item.id===metricId);if(chosen&&chosen.ministry)ministryId=chosen.ministry;render();};$('visualization').querySelectorAll('[data-add]').forEach(button=>button.onclick=()=>toggleParty(button.dataset.add));if(scrollToCard&&cardFocus){const focus=document.querySelector(`[data-card="${CSS.escape(cardFocus)}"]`);if(focus){focus.scrollIntoView({block:'center'});scrollToCard=false;}}syncUrl();}
function bindProposals(){document.querySelectorAll('[data-proposal]').forEach(button=>button.onclick=()=>openProposal(button.dataset.proposal));}
function openProposal(id){const card=data.proposals.find(item=>item.id===id);if(!card)return;lastFocus=document.activeElement;const current=data.ministries.find(item=>item.id===card.ministry);const url=card.url+(card.page?'#page='+card.page:'');const quote=card.excerpt&&card.excerpt!==card.summary?`<blockquote class="excerpt">${esc(card.excerpt)}</blockquote>`:'';const treatment=card.status==='contrastada'?(card.authoring==='modelo'?'Síntesis en castellano a partir del pasaje citado. La cita se conserva en el idioma del programa y se comprobó contra esa página.':'El texto de la ficha es un fragmento literal del programa. No añade medidas.'):'Se consultó el documento localizado y no hay una cita verificable para este ministerio.';const cited=programOf(party(card.party));const extra=card.also?`<h3>${esc(card.also.title)}</h3><p>${esc(card.also.summary)}</p>${card.also.excerpt?`<blockquote class="excerpt">${esc(card.also.excerpt)}</blockquote>`:''}<div class="detailmeta"><strong>Localización:</strong> ${esc(card.also.locator)}</div><a href="${esc(card.also.url+(card.also.page?'#page='+card.also.page:''))}" target="_blank" rel="noopener noreferrer">Abrir el otro programa ↗</a>`:'';$('detailBody').innerHTML=`<span class="eyebrow">${esc(label(card.party))} · ${esc(current.name)}</span><h2>${esc(card.title)}</h2><p>${esc(card.summary)}</p>${quote}<div class="detailmeta"><strong>Localización:</strong> ${esc(card.locator)}<br><strong>Documento:</strong> ${esc(cited?cited.title:'programa citado')}.<br><strong>Lectura de esta ficha:</strong> ${esc(card.retrieved||data.reviewed)}.<br><strong>Tratamiento:</strong> ${treatment}</div><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Abrir fuente original ↗</a>${extra}<p style="font-size:10px">El enlace abre el documento de la candidatura. El visor de PDF puede no respetar el salto de página en algunos dispositivos.</p>`;$('detail').showModal();$('closeDetail').focus();}
const indicatorName=id=>({1:'Decadencia y renacimiento',2:'Ultranacionalismo',3:'Pureza y exclusión',4:'Antipluralismo',5:'Culto al líder o al movimiento',6:'Glorificación de la fuerza',7:'Enemigo interno conspirativo'}[id]||'Indicador');
function openMark(id){markId=id;showPage('mark');$('markBody').querySelector('.back')?.focus();}
function renderWarning(card){const current=data.ministries.find(item=>item.id===card.ministry);const banner=(Array.isArray(card.warning.banner)?card.warning.banner:[]).filter(part=>part&&String(part).trim());const bannerHtml=banner.length?`<aside class="warningbanner"><p class="eyebrow">Qué intención hay detrás de esta propuesta</p>${banner.map(part=>`<p>${esc(part)}</p>`).join('')}</aside>`:'';const blocks=[['Pluralidad',card.warning.pluralism],['Inclusión',card.warning.inclusion],['Estado del bienestar',card.warning.welfare]].filter(([,body])=>body&&String(body).trim()).map(([title,body])=>`<h3>${title}</h3><p>${esc(body)}</p>`).join('');const where=card.page?`PDF · página ${card.page}`:(card.locator||'Documento oficial');const href=card.url+(card.page?'#page='+card.page:'');return `${bannerHtml}<div class="sectionhead"><span class="eyebrow">ADVERTENCIA SOBRE EL PASAJE</span><h2>Por qué este texto es peligroso.</h2><p>El documento es de ${esc(label(card.party))}, en ${esc(current?current.name:card.ministry)}. La advertencia es del pasaje, no de la candidatura.</p></div><p>Una democracia con pluralidad, inclusión y Estado del bienestar reconoce a las personas como iguales, admite más de una forma de vivir y sostiene la escuela, la sanidad y la vivienda como derechos.</p><h3>El pasaje</h3><blockquote class="excerpt">${esc(card.excerpt||'')}</blockquote>${blocks}<p><a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(where)} ↗</a></p>`;}
function renderMark(){const card=data.proposals.find(item=>item.id===markId);const back='<button class="textbutton back" data-page="explore">← Volver a la comparación</button>';let body;if(card&&card.warning)body=renderWarning(card);else{const rule='<p>En esta definición de trabajo, el fascismo es un ultranacionalismo populista de renacimiento nacional: la nación se presenta en decadencia y se propone regenerarla mediante la unidad, la pureza y la fuerza, subordinando al individuo y a las instituciones democráticas.</p><p>La advertencia solo aparece si el pasaje, en su literalidad, cumple de forma explícita al menos uno de los indicadores 3, 4, 5, 6 o 7, o combina el 1 y el 2. No se marca a la candidatura. Una política migratoria restrictiva, el patriotismo, el conservadurismo, el proteccionismo, la mano dura penal, el euroescepticismo o el populismo no bastan por sí solos.</p>';const flagged=card&&((card.reading&&card.reading.label==='fascista')||(card.also&&card.also.reading&&card.also.reading.label==='fascista'));if(!flagged)body=`<div class="sectionhead"><span class="eyebrow">LECTURA DEL PASAJE</span><h2>Esta ficha no lleva advertencia.</h2></div>${rule}<p>La lectura de este pasaje no cumple la regla. Por eso la tarjeta no está marcada.</p>`;else{const current=data.ministries.find(item=>item.id===card.ministry);const main=passageBlock(card.reading,card.excerpt,card.locator,card.url,card.page,false);const extra=card.also?passageBlock(card.also.reading,card.also.excerpt,card.also.locator,card.also.url,card.also.page,true):'';body=`<div class="sectionhead"><span class="eyebrow">LECTURA DEL PASAJE, NO DE LA CANDIDATURA</span><h2>Por qué este texto lleva advertencia.</h2><p>El documento es de ${esc(label(card.party))}, en ${esc(current?current.name:card.ministry)}. La marca es del pasaje.</p></div>${rule}${main}${extra}`;}}$('markBody').innerHTML=body+back;$('markBody').querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>showPage(button.dataset.page));}
function passageBlock(reading,excerpt,locator,url,page,second){if(!reading||reading.label!=='fascista')return '';const names=(reading.indicators||[]).map(indicatorName);const where=page?`PDF · página ${page}`:(locator||'Documento oficial');const href=url+(page?'#page='+page:'');return `<h3>${second?'El segundo programa':'El pasaje'}</h3><blockquote class="excerpt">${esc(excerpt||'')}</blockquote><p><strong>Indicador${names.length===1?'':'es'}:</strong> ${esc(names.join('; '))}.</p><p>${esc(reading.note||'')}</p><p><a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(where)} ↗</a></p>`;}

function showPage(id){if(id!=='mark')markId='';document.querySelectorAll('.page').forEach(page=>page.hidden=page.id!==id);document.querySelectorAll('nav [data-page]').forEach(button=>button.classList.toggle('active',button.dataset.page===id));if(id==='library')renderLibrary();if(id==='mark')renderMark();syncUrl();}
function renderLibrary(){const q=$('sourceSearch').value.toLocaleLowerCase('es'),rows=data.parties.filter(item=>(item.id+' '+item.name).toLocaleLowerCase('es').includes(q)).sort((a,b)=>label(a.id).localeCompare(label(b.id),'es'));$('libraryCount').textContent=rows.length+' candidaturas';$('sourceList').innerHTML=rows.map(item=>{const program=programOf(item),count=data.proposals.filter(card=>card.party===item.id&&card.status==='contrastada').length;const state=!program?'No hay programa publicado. No se elaboran fichas.':!item.reviewed?'Hay un documento localizado y las fichas siguen pendientes de contraste.':`${count} fichas contrastadas · ${program.status==='completo'?'programa completo':program.status==='bases'?'bases del programa':'avance de programa'}`;return `<article class="sourcecard"><h3><i class="swatch" style="background:${item.color}"></i> ${esc(label(item.id))}</h3><p>${esc(item.name)}</p><p>${esc(state)} · ${item.provinces.length} circunscripciones en el catálogo.</p>${program?`<a href="${esc(program.url)}" target="_blank" rel="noopener noreferrer">${esc(program.title)} ↗</a>${program.also?`<a href="${esc(program.also)}" target="_blank" rel="noopener noreferrer">Segundo programa ↗</a>`:''}`:'<p>No hay programa publicado.</p>'}</article>`;}).join('')||'<p class="nodata">Sin coincidencias.</p>';}
$('closeDetail').onclick=()=>$('detail').close();$('detail').addEventListener('close',()=>lastFocus?.focus());$('detail').addEventListener('click',event=>{if(event.target===$('detail')){const box=$('detail').getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)$('detail').close();}});document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>showPage(button.dataset.page));function revealCanvas(){const head=document.querySelector('.canvashead');const fix=()=>{if(head.getBoundingClientRect().top<12)head.scrollIntoView({block:'start'});};fix();requestAnimationFrame(fix);}document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{view=button.dataset.view;render();revealCanvas();});$('partySearch').oninput=renderParties;$('sourceSearch').oninput=renderLibrary;$('community').onchange=()=>{community=$('community').value;selected=selected.filter(id=>inCommunity(party(id)));render();};$('reset').onclick=()=>{selected=[];community='';ministryId='vivienda';view='matrix';metricId='';$('community').value='';$('partySearch').value='';render();};$('print').onclick=()=>window.print();$('share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Enlace de la comparación copiado.');}catch{toast('Puedes copiar la dirección de esta página para compartir la vista.');}};
(async()=>{try{const response=await fetch('data.json?v=22');if(!response.ok)throw Error('No se pudo cargar el catálogo.');data=await response.json();readUrl();$('community').insertAdjacentHTML('beforeend',data.communities.map(item=>`<option value="${esc(item.id)}">${esc(item.name)}</option>`).join(''));$('community').value=community;const contrasted=data.proposals.filter(item=>item.status==='contrastada').length,docs=data.parties.filter(item=>item.reviewed).length;const reviewed=data.reviewed.split('-').reverse().join('/');$('coverageText').textContent=`${contrasted} fichas contrastadas · ${docs} documentos leídos · ${data.parties.length} candidaturas en el catálogo. Lectura del ${reviewed}.`;$('catalogAttribution').innerHTML=`<strong>Origen del catálogo:</strong> ${esc(data.catalog_source.attribution)} <a href="${esc(data.catalog_source.boe)}" target="_blank" rel="noopener noreferrer">Consultar BOE ↗</a><p>Se conservan coaliciones y variantes territoriales. No son ${data.parties.length} partidos de ámbito estatal. Las fichas de una candidatura no se imputan a sus variantes o aliados, salvo cuando hay una referencia explícita: Front Ampli y Frente Amplio usan el programa del Frente Amplio, las coaliciones con el PSOE usan el programa del PSOE, UPN-PP usa el del PP, Unidad del Pueblo Canario usa el de Podemos, las candidaturas del PCTE usan su programa de lucha, y EH Bildu-ERC usa los programas de EH Bildu y de ERC. Si no hay esa referencia, la candidatura consta como sin programa y no se elabora ficha. Los ministerios son los departamentos del Gobierno vigentes según el Real Decreto 829/2023 consolidado.</p>`;$('updated').textContent='Lectura de programas · '+reviewed;render();if(markId)showPage('mark');}catch(error){$('error').hidden=false;$('error').textContent=error.message;}})();
